public class Clock {
  public static void main(String[] args) {
    int minutes = 0;
    for (int ms = 0; ms < 60*60*1000; ms++)
      if (ms % 60*1000 == 0)
        minutes++;
    System.out.println(minutes);
  }
}

class Livro {
  String titulo;
  int paginas;

  Livro(String titulo) {
    this(titulo, 100);
  }

  Livro(String titulo, int paginas) {
    this.titulo = titulo;
    this.paginas = paginas;
  }

  void alterar(String titulo, int paginas) {
    this.titulo = titulo;
    this.paginas += paginas;
  }

  public static void main(String[] args) {
    Livro a = new Livro("Java");
    Livro b = new Livro(a.titulo, a.paginas + 50);

    b.alterar("POO", 20);
    a.alterar(b.titulo, b.paginas);

    System.out.println(a.titulo + " " + a.paginas + " | "
        + b.titulo + " " + b.paginas);
  }
}

class Caixa {
  int valor;
  Caixa(int valor) {
    this.valor = valor;
  }
  static void alterar(Caixa a, Caixa b) {
    a.valor = a.valor + 2;
    a = b;
    a.valor = a.valor + 3;
  }
  public static void main(String[] args) {
    Caixa x = new Caixa(5);
    Caixa y = new Caixa(10);
    alterar(x, y);
    System.out.println(x.valor + " " + y.valor);
  }
}

class InTheLoop {
  public static void main(String[] args) {
    int end = Integer.MAX_VALUE;
    int start = end - 100;
    int count = 0;
    for (int i = start; i <= end; i++)
      count++;
    System.out.println(count);
  }
}
